#include "captured_scene.hpp"
#include "content.hpp"
#include "prop_physics.hpp"
#include <iostream>
#include <fstream>
#include <set>
using namespace ofo;
int main(int argc,char**argv){try{if(argc<3)throw std::runtime_error("data package [report]");Resources r(argv[1]);r.mount(fs::path(argv[2])/"capture_assets","capture_assets");std::set<std::string>seen;Json rows=Json::array();size_t total=0;for(const auto&stage:stage_catalog(r)){auto path=stage_geometry(stage);if(!seen.insert(path).second)continue;auto g=load_geometry(r,path,stage);size_t meshes=g.meshes.size(),triangles=g.triangles;auto report=append_captured_scene(g,r);if(meshes!=g.meshes.size()||triangles!=g.triangles)throw std::runtime_error("physics attachment changed native visual geometry");size_t affine=0;std::set<uint64_t>ids;for(auto&p:g.props){if(!ids.insert(p.id).second)throw std::runtime_error("duplicate prop identity");for(int i=0;i<3;i++){auto a=direction(p.transform,i==0?Vec{1,0,0}:i==1?Vec{0,1,0}:Vec{0,0,1});if(std::abs(length(a)-1)>.001f)affine++;}if(!(p.mass>0))throw std::runtime_error("native prop mass invalid");for(int k=0;k<3;k++)if(!std::isfinite(p.inertia[k])||p.inertia[k]<=0)throw std::runtime_error("prop inertia invalid");}btDefaultCollisionConfiguration config;btCollisionDispatcher dispatch(&config);btDbvtBroadphase broad;btSequentialImpulseConstraintSolver solver;ContactWorld world(&dispatch,&broad,&solver,&config);world.setGravity({0,-9.81f,0});{PropPhysics props(world,g.props);world.stepSimulation(.01f,0);if(props.released()!=0||!props.snapshot()->empty())throw std::runtime_error("untouched props moved");}report["geometry"]=path;report["affine_basis_columns"]=affine;report["visual_meshes_preserved"]=meshes;report["triangles_preserved"]=triangles;rows.push_back(report);total+=g.props.size();}Json out={{"unique_worlds",seen.size()},{"dynamic_bodies",total},{"worlds",rows},{"scope","native CPU geometry/body construction and untouched held state; no Windows render verification"}};if(argc>3){std::ofstream f(argv[3]);f<<out.dump(2)<<'\n';}std::cout<<out.dump(2)<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
